    text-align: center;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
  }

  th, td {
    text-align: left;
    padding: 2px 0;
  }

  th {
    border-bottom: 1px dashed #000;
  }

  tfoot td {
    border-top: 1px dashed #000;
    font-weight: bold;
  }

  .totals {
    margin-top: 5px;
    border-top: 1px dashed #000;
    border-bottom: 1px dashed #000;
    padding: 4px 0;
  }

  @page {
